'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var pkg = require( './../package.json' ).name;
var isEqual = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'uint32'
};

var N = 128;
var x = discreteUniform( 2*N, 0, UINT32_MAX, options );
var y = discreteUniform( 2*N, 0, UINT32_MAX, options );
var values1 = [];
var values2 = [];
var i;
var j;
x[0] = y[0];
x[1] = y[1];
for ( i = 0; i < N; i++ ) {
	j = 2 * i;
	values1.push( Uint64.of( x[ j ], x[ j+1 ] ) );
	values2.push( Uint64.of( y[ j ], y[ j+1 ] ) );
}


// MAIN //

bench( pkg, function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = isEqual( values1[ i%N ], values2[ i%N ] );
		if ( typeof out !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( out ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
